// Source-independent 2.5D planes. No reconstructed volumetric city is claimed.
import {drawAssetMedia} from './effect-library.js?v=motion-v70';
import {recordSceneAsset} from './scene-geometry.js?v=motion-v70';
export const ruinedWindowSources={historyWindowCity:'ruined-window-city-v55.png',historyWindowPerson:'ruined-window-person-v55.png',historyWindowWall:'ruined-window-wall-v55.png'};
export const ruinedWindowDefaults={historyWindowEnabled:true,historyWindowStart:11.758,historyWindowEnd:20,historyWindowSpeed:1,historyWindowDirection:'right',historyWindowPullback:260,historyWindowPersonDepth:950,historyWindowCityDepth:2800,historyWindowWallDepth:750,historyWindowPersonX:-240,historyWindowPersonY:-45,historyWindowPersonWidth:730,historyWindowPersonTravel:0,historyWindowCityTravel:0,historyWindowWallTravel:0,historyWindowCityScale:1.26,historyWindowCityX:0,historyWindowCityY:0,historyWindowWallX:-600,historyWindowWallY:-60,historyWindowWallWidth:2400,historyWindowCityBlur:1.6,historyWindowPersonBlur:0,historyWindowWallBlur:.5,historyWindowPersonBrightness:.84,historyWindowCityBrightness:.83,historyWindowWallBrightness:.65};
const clamp=x=>Math.max(0,Math.min(1,x));
export function ruinedWindowState(age,input={}){const f={...ruinedWindowDefaults,...input},duration=Math.max(.1,f.historyWindowEnd-f.historyWindowStart),q=clamp((age-f.historyWindowStart)*Math.max(.05,f.historyWindowSpeed)/duration),sign=['left','up'].includes(f.historyWindowDirection)?-1:1,vertical=['up','down'].includes(f.historyWindowDirection),scale=z=>Math.max(100,z)/(Math.max(100,z)+Math.max(0,f.historyWindowPullback)*q);return {q,vertical,sign,personScale:scale(f.historyWindowPersonDepth),cityScale:scale(f.historyWindowCityDepth),wallScale:scale(f.historyWindowWallDepth),personOffset:f.historyWindowPersonTravel*q*sign,cityOffset:f.historyWindowCityTravel*q*sign,wallOffset:f.historyWindowWallTravel*q*sign};}
export function paintRuinedWindow(c,age,images,input={}){const f={...ruinedWindowDefaults,...input},media=slot=>images[f.historySourceBindings?.[slot]||slot],city=media('historyWindowCity'),person=media('historyWindowPerson'),wall=media('historyWindowWall');if(!f.historyWindowEnabled||![city,person,wall].every(im=>im&&(im.naturalWidth||im.width)))return false;const s=ruinedWindowState(age,f),iw=im=>im.naturalWidth||im.width,ih=im=>im.naturalHeight||im.height;function paint(slot,rect,blur,light){const im=media(slot);c.save();c.filter=`grayscale(1) brightness(${Math.max(.1,light)}) blur(${Math.max(0,blur)}px)`;drawAssetMedia(c,im,rect,f,age);c.restore();const actual=f.historySourceBindings?.[slot]||slot;recordSceneAsset(c,{id:actual,kind:'image',assetSlot:actual,name:actual},rect);}const shift=(rect,offset)=>{rect[s.vertical?1:0]+=offset;return rect;};c.save();c.fillStyle='#101113';c.fillRect(0,0,960,540);
// Overscan covers all camera drift at default settings without a translucent fade.
const minCover=Math.max(1+2*(Math.abs(f.historyWindowCityX)+(s.vertical?0:Math.abs(f.historyWindowCityTravel)))/960,1+2*(Math.abs(f.historyWindowCityY)+(s.vertical?Math.abs(f.historyWindowCityTravel):0))/540)*(1+Math.max(0,f.historyWindowPullback)/Math.max(100,f.historyWindowCityDepth)),k=Math.max(960/iw(city),540/ih(city))*Math.max(f.historyWindowCityScale,minCover)*s.cityScale,w=iw(city)*k,h=ih(city)*k;paint('historyWindowCity',shift([480-w/2+f.historyWindowCityX,270-h/2+f.historyWindowCityY,w,h],s.cityOffset),f.historyWindowCityBlur,f.historyWindowCityBrightness);
const wr=[f.historyWindowWallX,f.historyWindowWallY,f.historyWindowWallWidth,f.historyWindowWallWidth*ih(wall)/iw(wall)];wr[0]+=(wr[2]-wr[2]*s.wallScale)/2;wr[2]*=s.wallScale;wr[3]*=s.wallScale;paint('historyWindowWall',shift(wr,s.wallOffset),f.historyWindowWallBlur,f.historyWindowWallBrightness);
const pw=f.historyWindowPersonWidth*s.personScale,ph=pw*ih(person)/iw(person),pr=[480+(f.historyWindowPersonX-480)*s.personScale,f.historyWindowPersonY+(f.historyWindowPersonWidth*ih(person)/iw(person)-ph),pw,ph];paint('historyWindowPerson',shift(pr,s.personOffset),f.historyWindowPersonBlur,f.historyWindowPersonBrightness);c.restore();return s;}
